const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const _ = require('lodash');

const PROTO_PATH = __dirname + '/config.proto';

const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: true,
  longs: String,
  enums: String,
  defaults: true,
  oneofs: true
});

const configProto = grpc.loadPackageDefinition(packageDefinition).configservice;

// In-memory configuration store
let configStore = {
  database: { host: 'rds-internal.vpc.local', port: 5432 },
  cache: { ttl: 300, maxSize: 1000 },
  features: { enableBeta: false, debugMode: false }
};

// Deep merge utility for configuration updates
function deepMergeConfig(target, source) {
  // Recursively merge source into target
  for (const key of Object.keys(source)) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      if (!target[key]) target[key] = {};
      deepMergeConfig(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

// gRPC service implementations
function getConfig(call, callback) {
  const section = call.request.section;
  if (section && configStore[section]) {
    callback(null, { config_json: JSON.stringify(configStore[section]) });
  } else {
    callback(null, { config_json: JSON.stringify(configStore) });
  }
}

function updateConfig(call, callback) {
  try {
    const updates = JSON.parse(call.request.config_json);
    const section = call.request.section;

    if (section) {
      if (!configStore[section]) configStore[section] = {};
      deepMergeConfig(configStore[section], updates);
    } else {
      // Merge at root level - allows updating multiple sections
      deepMergeConfig(configStore, updates);
    }

    callback(null, { success: true, message: 'Configuration updated' });
  } catch (err) {
    callback(null, { success: false, message: `Parse error: ${err.message}` });
  }
}

function healthCheck(call, callback) {
  const status = {
    uptime: process.uptime(),
    memoryUsage: process.memoryUsage().heapUsed,
    isAdmin: ({}).isAdmin || false,
    polluted: ({}).polluted || 'clean'
  };
  callback(null, { status_json: JSON.stringify(status) });
}

// Middleware-style auth check using prototype chain
function checkAuthorization(metadata) {
  const token = metadata.get('authorization')[0];
  const basePerms = {};
  // If prototype is polluted with admin:true, this check passes
  if (basePerms.admin === true) {
    return { authorized: true, role: 'admin' };
  }
  // Normal token validation
  return validateToken(token);
}

function validateToken(token) {
  const validTokens = ['svc-config-reader', 'svc-config-writer'];
  if (validTokens.includes(token)) {
    return { authorized: true, role: 'service' };
  }
  return { authorized: false, role: 'none' };
}

function main() {
  const server = new grpc.Server();
  server.addService(configProto.ConfigService.service, {
    GetConfig: getConfig,
    UpdateConfig: updateConfig,
    HealthCheck: healthCheck
  });

  const bindAddress = '0.0.0.0:50051';
  server.bindAsync(bindAddress, grpc.ServerCredentials.createInsecure(), (err, port) => {
    if (err) {
      console.error('Failed to bind:', err);
      process.exit(1);
    }
    console.log(`Config service listening on ${bindAddress}`);
    server.start();
  });
}

main();
